CREATE TABLE cloud_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES cloud_users, target text NOT NULL UNIQUE, password_hash text, verified boolean NOT NULL DEFAULT false);
CREATE TABLE cloud_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), target text NOT NULL, purpose text NOT NULL, user_id uuid REFERENCES cloud_users, digest text NOT NULL, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_staff (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, mfa_secret text NOT NULL, last_totp bigint NOT NULL DEFAULT -1, role text NOT NULL CHECK(role IN ('owner','support','finance','operator')), disabled boolean NOT NULL DEFAULT false);
CREATE TABLE cloud_devices (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES cloud_users, name text NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES cloud_users, staff_id uuid REFERENCES cloud_staff, device_id uuid REFERENCES cloud_devices, digest text NOT NULL UNIQUE, refresh_digest text UNIQUE, family uuid NOT NULL DEFAULT gen_random_uuid(), csrf text NOT NULL, expires_at timestamptz NOT NULL, refresh_expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK((user_id IS NULL) <> (staff_id IS NULL)));
CREATE TABLE cloud_refresh_history (digest text PRIMARY KEY, family uuid NOT NULL);
CREATE TABLE cloud_desktop_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), digest text NOT NULL UNIQUE, user_id uuid NOT NULL REFERENCES cloud_users, challenge text NOT NULL, redirect_uri text NOT NULL, device_id uuid NOT NULL, device_name text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE cloud_models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), config jsonb NOT NULL, tested_at timestamptz, enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), config jsonb NOT NULL, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_agreements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES cloud_users, product text NOT NULL DEFAULT 'hosted-ai', price_id uuid NOT NULL REFERENCES cloud_prices, channel text NOT NULL, status text NOT NULL DEFAULT 'pending', next_at timestamptz, scenario text NOT NULL DEFAULT 'success', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX cloud_one_agreement ON cloud_agreements(user_id,product) WHERE status IN ('pending','active','canceling');
CREATE TABLE cloud_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES cloud_users, price_id uuid NOT NULL REFERENCES cloud_prices, snapshot jsonb NOT NULL, channel text NOT NULL, key text NOT NULL, status text NOT NULL DEFAULT 'pending', agreement_id uuid REFERENCES cloud_agreements, cycle_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,key), UNIQUE(agreement_id,cycle_at));
CREATE TABLE cloud_payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES cloud_orders, channel text NOT NULL, status text NOT NULL DEFAULT 'pending', provider_state text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, order_id uuid REFERENCES cloud_orders, agreement_id uuid REFERENCES cloud_agreements, kind text NOT NULL, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES cloud_users, order_id uuid NOT NULL UNIQUE REFERENCES cloud_orders, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, anchor timestamptz NOT NULL, anchor_offset int NOT NULL DEFAULT 0, revoked_at timestamptz, CHECK(ends_at>starts_at));
CREATE TABLE cloud_credit_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES cloud_users, term_id uuid NOT NULL REFERENCES cloud_terms, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, allowance int NOT NULL CHECK(allowance>0), available int NOT NULL DEFAULT 0 CHECK(available>=0), reserved int NOT NULL DEFAULT 0 CHECK(reserved>=0), state text NOT NULL DEFAULT 'scheduled', UNIQUE(term_id,starts_at));
CREATE TABLE cloud_ai_requests (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES cloud_users, device_id uuid REFERENCES cloud_devices, turn_id text NOT NULL, fingerprint text NOT NULL, model_id uuid NOT NULL REFERENCES cloud_models, rate_snapshot jsonb NOT NULL, period_id uuid NOT NULL REFERENCES cloud_credit_periods, reserved int NOT NULL CHECK(reserved>=0), status text NOT NULL, input_tokens int, output_tokens int, cost int, cancel_requested boolean NOT NULL DEFAULT false, upstream_id text, error_code text, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE cloud_credit_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES cloud_users, period_id uuid NOT NULL REFERENCES cloud_credit_periods, kind text NOT NULL, amount int NOT NULL, key text NOT NULL UNIQUE, request_id uuid REFERENCES cloud_ai_requests, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES cloud_orders, status text NOT NULL DEFAULT 'pending', reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, kind text NOT NULL, payload jsonb NOT NULL, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending', locked_until timestamptz, attempts int NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX cloud_jobs_due ON cloud_jobs(status,due_at);
CREATE TABLE cloud_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, resource_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cloud_test_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), challenge_id uuid NOT NULL REFERENCES cloud_challenges, target text NOT NULL, code text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE cloud_rate_limits (key text PRIMARY KEY, count int NOT NULL, expires_at timestamptz NOT NULL);
